/* ---------- 9. driver de export ---------- */
var PPTX_CDN='https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js';
var libP=null;
function lib(){
  if(libP)return libP;
  libP=new Promise(function(res,rej){
    if(window.PptxGenJS)return res(window.PptxGenJS);
    var sc=document.createElement('script');sc.src=PPTX_CDN;
    sc.onload=function(){window.PptxGenJS?res(window.PptxGenJS):rej(new Error('PptxGenJS no cargó'));};
    sc.onerror=function(){rej(new Error('no se pudo cargar PptxGenJS desde el CDN'));};
    document.head.appendChild(sc);
  });
  return libP;
}
function buildDeck(ids){
  return lib().then(function(Lib){
    var pptx=new Lib();
    pptx.defineLayout({name:'MAGOYA16x9',width:SW,height:SH});
    pptx.layout='MAGOYA16x9';
    pptx.author='Magoya';pptx.company='Magoya';pptx.title='Magoya · Deck kit';
    var chain=Promise.resolve();
    ids.forEach(function(id,i){
      chain=chain.then(function(){
        var fn=SPEC[id];
        if(!fn){console.warn('[deck-kit] sin spec para',id);return;}
        var shapes=fn(String(i+3).padStart(2,'0'));
        var sl=pptx.addSlide();
        return paint(pptx,sl,shapes);
      });
    });
    return chain.then(function(){return pptx;});
  });
};
